import{_ as t,D as o,c as n,j as a,a as e,I as i,a2 as c,o as r}from"./chunks/framework.DdOM6S6U.js";const k=JSON.parse('{"title":"Comparison Table","description":"","frontmatter":{"sidebarPos":11,"sidebarTitle":"Comparison Table"},"headers":[],"relativePath":"guide/form-inputs/input-comparison-table.md","filePath":"guide/form-inputs/input-comparison-table.md","lastUpdated":1777448730000}'),l={name:"guide/form-inputs/input-comparison-table.md"},p={id:"comparison-table",tabindex:"-1"},d=a("a",{class:"header-anchor",href:"#comparison-table","aria-label":'Permalink to "Comparison Table <Badge type="tip" text="^0.9.2" />"'},"​",-1),u=c(`<p>The <code>v-input-comparison-table</code> component offers a comparison table with and selecting a radio input in basis. This is useful for showing detailed information about to select from multi selected items on table structure</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><p>You can consider it just like select input in regards to <strong>items</strong> attribute, you can use &#39;connect&#39; attribute like &#39;ModuleName:RouteName|repository&#39; or &#39;repository&#39; attribute like RouteNameRepository::class. But in some cases, it can be crucial relational data sets for rendering items especially on column fields of table, you can use &#39;scopes&#39; argument of repository:list method for this cases.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  [</span></span>
<span class="line"><span>    &#39;type&#39; =&gt; &#39;comparison-table&#39;,</span></span>
<span class="line"><span>    &#39;items&#39; =&gt; [],</span></span>
<span class="line"><span>    &#39;connector&#39; =&gt; &#39;{ModuleName}:{RouteName}|repository:list:withs={RelationshipName}&#39;,</span></span>
<span class="line"><span>    &#39;comparators&#39; =&gt; [</span></span>
<span class="line"><span>        &#39;features&#39; =&gt; [</span></span>
<span class="line"><span>            &#39;key&#39; =&gt; &#39;features&#39;, // not required, specifies which attribute to take into account</span></span>
<span class="line"><span>            &#39;field&#39; =&gt; &#39;description&#39;, // not required, specifies which field of object to use,</span></span>
<span class="line"><span>            &#39;itemClasses&#39; =&gt; &#39;text-success font-weight-bold&#39;, // add class into span tag of each cell of row</span></span>
<span class="line"><span>            &#39;title&#39; =&gt; &#39;My Features&#39;, // optional, comparator cell title</span></span>
<span class="line"><span>        ],</span></span>
<span class="line"><span>        &#39;prices&#39; =&gt; []</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>  ],</span></span></code></pre></div><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>This component was introduced in [v0.9.2]</p></div><h2 id="hydrate" tabindex="-1">Hydrate <a class="header-anchor" href="#hydrate" aria-label="Permalink to &quot;Hydrate&quot;">​</a></h2><p><strong>Class:</strong> <code>ComparisonTableHydrate</code><strong>Config type:</strong> <code>comparison-table</code><strong>Output type:</strong> <code>input-comparison-table</code> → <code>VInputComparisonTable</code></p><p>The hydrate sets <code>type</code> to <code>input-comparison-table</code> and automatically adds each key of the <code>comparators</code> map to the model&#39;s <code>with()</code> eager loads via the <code>withs()</code> method. This ensures related data is available when the table renders.</p><h3 id="schema-defaults" tabindex="-1">Schema Defaults <a class="header-anchor" href="#schema-defaults" aria-label="Permalink to &quot;Schema Defaults&quot;">​</a></h3><p>No default keys are set. All schema is driven by the <code>comparators</code> and <code>connector</code> / <code>items</code> you provide.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="/system-reference/hydrates">Hydrates reference</a> — Resolution table and schema contract</li><li><a href="/guide/generics/relationships">Relationships</a> — Using <code>connector</code> to load remote data</li></ul>`,12);function h(m,b,f,g,y,_){const s=o("Badge");return r(),n("div",null,[a("h1",p,[e("Comparison Table "),i(s,{type:"tip",text:"^0.9.2"}),e(),d]),u])}const v=t(l,[["render",h]]);export{k as __pageData,v as default};
